using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using MarketSphere.Domain.Entities.Infrastructure;
namespace MarketSphere.Infrastructure.Persistence.Configurations.Infrastructure;
public sealed class ApprovalStepAssigneeConfiguration : IEntityTypeConfiguration<ApprovalStepAssignee> { public void Configure(EntityTypeBuilder<ApprovalStepAssignee> builder) { builder.ToTable("ApprovalStepAssignees", t => t.HasCheckConstraint("CK_ApprovalStepAssignees_OneReference", "(CASE WHEN [RoleID] IS NULL THEN 0 ELSE 1 END + CASE WHEN [DesignationID] IS NULL THEN 0 ELSE 1 END + CASE WHEN [UserID] IS NULL THEN 0 ELSE 1 END + CASE WHEN [EmployeeID] IS NULL THEN 0 ELSE 1 END) = 1")); builder.HasKey(x => x.ApprovalStepAssigneeID); builder.Property(x => x.AssigneeType).HasConversion<int>(); builder.HasIndex(x => new { x.ApprovalStepDefinitionID, x.AssigneeType, x.RoleID, x.DesignationID, x.UserID, x.EmployeeID }).IsUnique(); builder.HasOne(x => x.ApprovalStepDefinition).WithMany(x => x.Assignees).HasForeignKey(x => x.ApprovalStepDefinitionID).OnDelete(DeleteBehavior.Restrict); builder.HasOne(x => x.Role).WithMany().HasForeignKey(x => x.RoleID).OnDelete(DeleteBehavior.Restrict); builder.HasOne(x => x.Designation).WithMany().HasForeignKey(x => x.DesignationID).OnDelete(DeleteBehavior.Restrict); builder.HasOne(x => x.User).WithMany().HasForeignKey(x => x.UserID).OnDelete(DeleteBehavior.Restrict); builder.HasOne(x => x.Employee).WithMany().HasForeignKey(x => x.EmployeeID).OnDelete(DeleteBehavior.Restrict); } }
